// Bandeira do Uruguai (270 x 180): nove listras e o sol no canto.
const FLAG_ART =
  '<rect width="270" height="180" fill="#ffffff" stroke="#9aa5ae" stroke-width="3"/>' +
  '<path fill="#0038a8" d="M100 20H270V40H100ZM100 60H270V80H100ZM0 100H270V120H0ZM0 140H270V160H0Z"/>' +
  `<g transform="translate(-29.2 -29.2) scale(3.3)"><path fill="#fcd116" stroke="#8c6a00" stroke-width="0.25" d="${SUN}"/></g>`

// Fundo liso, com os símbolos só nos quatro cantos, longe do texto.
const SCENE =
  '<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%">' +
  '<style>' +
  '.bg { fill: #e8f2f8 } .edge { fill: none; stroke: none }' +
  '@media (prefers-color-scheme: dark) { .bg { fill: #120c0d } .edge { stroke: #f2b705; stroke-width: 10 } }' +
  '</style>' +
  CREST_DEFS +
  '<rect class="bg" width="100%" height="100%"/>' +
  corner('xMinYMin', 'translate(30 110) scale(0.45)', FLAG_ART) +
  corner('xMaxYMin', 'translate(894 110) scale(0.16)', CREST_ART) +
  corner('xMinYMax', 'translate(30 877) scale(0.16)', CREST_ART) +
  corner('xMaxYMax', 'translate(848.5 889) scale(0.45)', FLAG_ART) +
  '</svg>'

const BASE: ThemeSetArgs = {
  colors: theme,
  backdrop: { scene: 'cantos' },
}

const LOOK: ThemeSetArgs = {
  ...BASE,
  style: {
    Heading: { color: RED, fontWeight: 'bold' },
    AssistantMessage: {
      color: '#0b2545',
      backgroundColor: '#e4f3fc',
      borderColor: CELESTE,
      borderWidth: 2,
      radius: 14,
      padding: 14,
      shadow: { y: 2, blur: 6, color: '#f2b70555' },
    },
    ToolUse: { color: '#0b2545', backgroundColor: '#f2b705ee', radius: 8, paddingX: 8 },
  },
}

export const register: Register = on => {
  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.props.scene !== 'cantos' || (e.surface !== 'desktop' && e.surface !== 'mobile')) {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)

    return <Svg source={SCENE} alt="Bandeira do Uruguai e escudo do Flamengo nos cantos" />
  })

  on('session.start', async ($, e, next) => {
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))

    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }
    let set
    try {
      set = await $.theme.set(LOOK)
    } catch (error) {
      $.ui.log(String(error))
      set = await $.theme.set(BASE)
    }
    if (!set.isDrawn) {
      $.ui.status(set.reason)
    }

    return next(e)
  })
}
